// GENERATED by benchtop firmware.ts from project.json.
// Bring-up sketch, built only by [env:bringup]. Regenerated on every run; do not edit.
// Prints the pin map, scans I2C, toggles each output once, then reports inputs every second.
// Outputs are driven HIGH for 400 ms: disconnect motors, relays and anything that must not move.
#include <Arduino.h>
#include <Wire.h>
#include "pins.h"

struct Expect {
  const char* part;
  const uint8_t* addrs;
  uint8_t count;
};
static const uint8_t ADDRS_0[] = {0x3C, 0x3D};
static const uint8_t ADDRS_1[] = {0x76, 0x77};
static const Expect EXPECTED[] = {
  {"0.96 inch SSD1306 OLED, 128x64, I2C (oled)", ADDRS_0, 2},
  {"BME280 breakout (GY-BME280, 3.3 V, I2C) (env)", ADDRS_1, 2},
};

static void printPinMap() {
  Serial.println("[pins] pin map from pins.h");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_I2C_SDA", PIN_I2C_SDA, "I2C_SDA: oled.SDA, env.SDA");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_I2C_SCL", PIN_I2C_SCL, "I2C_SCL: oled.SCL, env.SCL");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_BUTTON", PIN_BUTTON, "BUTTON: btn.1");
}

static bool probe(uint8_t addr) {
  Wire.beginTransmission(addr);
  return Wire.endTransmission() == 0;
}

static void scanI2c() {
  Wire.begin(PIN_I2C_SDA, PIN_I2C_SCL);
  Serial.println("[i2c] scanning 0x08-0x77");
  bool seen[128] = {false};
  int count = 0;
  for (uint8_t a = 0x08; a <= 0x77; a++) {
    if (probe(a)) {
      seen[a] = true;
      count++;
      Serial.printf("  device at 0x%02X\n", a);
    }
  }
  if (count == 0) Serial.println("  nothing answered: check 3V3, GND, SDA/SCL and that the pins are not swapped");
  for (const Expect& e : EXPECTED) {
    int hit = -1;
    for (uint8_t i = 0; i < e.count; i++) {
      if (seen[e.addrs[i]]) { hit = e.addrs[i]; break; }
    }
    if (hit >= 0) Serial.printf("[ OK ] %s found at 0x%02X\n", e.part, hit);
    else {
      Serial.printf("[MISS] %s missing, expected at", e.part);
      for (uint8_t i = 0; i < e.count; i++) Serial.printf(" 0x%02X", e.addrs[i]);
      Serial.println();
    }
  }
}

void setup() {
  Serial.begin(115200);
  uint32_t t0 = millis();
  while (!Serial && millis() - t0 < 3000) delay(10);
  delay(300);
  Serial.println("\n=== bring-up: luft ===");
  printPinMap();
  scanI2c();
  Serial.println("[out] no output pins in this project");
  pinMode(PIN_BUTTON, INPUT_PULLUP);
  Serial.println("[in] reporting inputs once a second");
}

void loop() {
  Serial.printf("[in] t=%lus", (unsigned long)(millis() / 1000));
  Serial.printf(" PIN_BUTTON=%d", digitalRead(PIN_BUTTON));
  Serial.println();
  delay(1000);
}
